dashboard.definition:
{
  "title": "Gear and Sports",
  "description": "Recorded gear usage can be incomplete. Names are preserved; correct aliases through overrides. No combined pace is calculated across sports.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.table",
      "title": "Recorded gear usage",
      "dataSources": {
        "primary": "ds_0"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.column",
      "title": "Gear distance by month",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_2": {
      "type": "splunk.table",
      "title": "Strength sessions",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_3": {
      "type": "splunk.table",
      "title": "Sport summaries",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    }
  },
  "dataSources": {
    "ds_0": {
      "type": "ds.search",
      "name": "Recorded gear usage",
      "options": {
        "query": "index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens_ops sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(isnum($time.earliest|s$),tonumber($time.earliest|s$),relative_time(now(),$time.earliest|s$)) AND timestamp<=if($time.latest|s$=\"now\",now(),if(isnum($time.latest|s$),tonumber($time.latest|s$),relative_time(now(),$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where $quality_mode|s$!=\"Validated\" OR (distance_valid=1 AND duration_valid=1) | eval display_distance=distance_m/if($units|s$=\"Imperial\",1609.344,1000) | stats count AS activities sum(display_distance) AS distance sum(moving_time_s) AS seconds BY gear sport | eval hours=round(seconds/3600,2) | fields gear sport activities distance hours",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "ds_1": {
      "type": "ds.search",
      "name": "Gear distance by month",
      "options": {
        "query": "index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens_ops sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(isnum($time.earliest|s$),tonumber($time.earliest|s$),relative_time(now(),$time.earliest|s$)) AND timestamp<=if($time.latest|s$=\"now\",now(),if(isnum($time.latest|s$),tonumber($time.latest|s$),relative_time(now(),$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where $quality_mode|s$!=\"Validated\" OR (distance_valid=1 AND duration_valid=1) | eval display_distance=distance_m/if($units|s$=\"Imperial\",1609.344,1000) | chart sum(display_distance) OVER local_month BY gear",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Strength sessions",
      "options": {
        "query": "index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens_ops sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(isnum($time.earliest|s$),tonumber($time.earliest|s$),relative_time(now(),$time.earliest|s$)) AND timestamp<=if($time.latest|s$=\"now\",now(),if(isnum($time.latest|s$),tonumber($time.latest|s$),relative_time(now(),$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where sport=\"Weight Training\" | table activity_id local_date moving_time_s average_hr sets reps",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Sport summaries",
      "options": {
        "query": "index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens_ops sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(isnum($time.earliest|s$),tonumber($time.earliest|s$),relative_time(now(),$time.earliest|s$)) AND timestamp<=if($time.latest|s$=\"now\",now(),if(isnum($time.latest|s$),tonumber($time.latest|s$),relative_time(now(),$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | stats count AS activities sum(moving_time_s) AS seconds sum(elevation_gain_m) AS elevation_m BY sport | eval hours=round(seconds/3600,2) | fields sport activities hours elevation_m",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": [
          {
            "label": "All",
            "value": "All"
          },
          {
            "label": "Run",
            "value": "Run"
          },
          {
            "label": "Ride",
            "value": "Ride"
          },
          {
            "label": "Hike",
            "value": "Hike"
          },
          {
            "label": "Alpine Ski",
            "value": "Alpine Ski"
          },
          {
            "label": "Weight Training",
            "value": "Weight Training"
          },
          {
            "label": "Workout",
            "value": "Workout"
          },
          {
            "label": "Walk",
            "value": "Walk"
          },
          {
            "label": "Swim",
            "value": "Swim"
          },
          {
            "label": "Nordic Ski",
            "value": "Nordic Ski"
          },
          {
            "label": "Backcountry Ski",
            "value": "Backcountry Ski"
          },
          {
            "label": "Kayaking",
            "value": "Kayaking"
          }
        ]
      }
    },
    "gear": {
      "type": "input.text",
      "title": "Gear (exact name or All)",
      "options": {
        "token": "gear",
        "defaultValue": "All"
      }
    },
    "quality": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {
        "item": "viz_0",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 300
        }
      },
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 300,
          "w": 1200,
          "h": 300
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 0,
          "y": 600,
          "w": 1200,
          "h": 300
        }
      },
      {
        "item": "viz_3",
        "type": "block",
        "position": {
          "x": 0,
          "y": 900,
          "w": 1200,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "time",
      "sport",
      "gear",
      "quality",
      "units",
      "snapshot"
    ]
  }
}
